use std::{env, fs, process};

struct Entry {
    key: String,
    value: String,
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn main() {
    let path = match env::args().nth(1) {
        Some(path) => path,
        None => fail("missing input path"),
    };
    let input = match fs::read_to_string(&path) {
        Ok(input) => input,
        Err(error) => fail(format!("cannot read '{}': {}", path, error)),
    };

    let mut entries: Vec<Entry> = Vec::new();
    for (line_number, raw_line) in input.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        if line.is_empty() {
            fail(format!("line {}: malformed record", line_number + 1));
        }
        let fields: Vec<&str> = line.split('|').collect();
        if fields.len() != 3 {
            fail(format!("line {}: malformed record", line_number + 1));
        }

        match fields[0] {
            "put" => {
                if fields[1].is_empty() {
                    fail(format!("line {}: empty key", line_number + 1));
                }
                if let Some(entry) = entries.iter_mut().find(|entry| entry.key == fields[1]) {
                    entry.value.clear();
                    entry.value.push_str(fields[2]);
                } else {
                    entries.push(Entry {
                        key: fields[1].to_owned(),
                        value: fields[2].to_owned(),
                    });
                }
            }
            "delete" => {
                if fields[1].is_empty() || !fields[2].is_empty() {
                    fail(format!("line {}: malformed delete record", line_number + 1));
                }
                if let Some(position) = entries.iter().position(|entry| entry.key == fields[1]) {
                    entries.remove(position);
                }
            }
            kind => fail(format!(
                "line {}: unknown record kind '{}'",
                line_number + 1,
                kind
            )),
        }
    }

    let mut output = String::new();
    for entry in entries {
        output.push_str(&entry.key);
        output.push('=');
        output.push_str(&entry.value);
        output.push('\n');
    }
    print!("{}", output);
}
